long long BIT[MAXN * 2]; // Fenwick tree for range updates

void bit_add(int idx, long long val) {
    while (idx <= timer) {
        BIT[idx] += val;
        idx += idx & -idx;
    }
}

void range_add(int l, int r, long long val) {
    bit_add(l, val);
    bit_add(r + 1, -val);
}

long long bit_query(int idx) {
    long long res = 0;
    while (idx > 0) {
        res += BIT[idx];
        idx -= idx & -idx;
    }
    return res;
}

