typedef long long ll;

/*
We maintain the company tree dynamically with:
- subtree range updates/query by Euler-tour intervals
- adding a new node as the last child

Key fact:
If each newly added node is appended after the whole current subtree of its parent
in DFS order, then every subtree is always a contiguous interval [tin[v], tout[v]].
When a new node is inserted into the Euler order, all later positions shift by +1.

To support this, we use an implicit treap representing Euler-order positions.
Each treap node corresponds to one worker.
For every worker v:
- its treap node stores current salary base value
- subtree of v in company corresponds to a contiguous segment in treap

Operations:
1) add x to subtree(v): range add on segment [tin[v], tout[v]]
2) sum subtree(v): range sum on segment
3) add new worker u under parent p with salary s:
   insert new treap node right after current subtree of p,
   making it the last node in p's subtree.
   Then increment subtree sizes of p and all ancestors by 1.
   We do that via parent climbing; total O(height).
This is acceptable only if constraints are modest, but problem statement here omits them.
To keep solution robust, we instead maintain ancestor chain with parent pointers and
update tout by climbing. This is simple and correct.

All interval positions are obtained by rank in treap:
- tin[v] is fixed as insertion position of v at creation
- but later insertions before/inside may shift ranks, so we cannot store static tin/tout as integers.
Instead we store direct treap-node pointer for each worker, and compute current rank(node)
in O(log N). For subtree end, we store subtree_size_company[v] (#workers in subtree),
so current interval is [rank(v), rank(v)+subtree_size_company[v)-1].

Thus:
- rank(v): current position of v in treap
- company subtree size maintained by parent climbing on insertion

Complexities:
- query/update: O(log N)
- insertion: O(log N + height)
*/

typedef struct Node {
    struct Node *l, *r, *p;
    unsigned pri;
    int sz;
    ll val, sum, lazy;
    int id;
} Node;

static inline int getsz(Node *t) { return t ? t->sz : 0; }
static inline ll getsum(Node *t) { return t ? t->sum : 0; }

void apply(Node *t, ll add) {
    if (!t) return;
    t->val += add;
    t->sum += add * getsz(t);
    t->lazy += add;
}

void push(Node *t) {
    if (!t || t->lazy == 0) return;
    apply(t->l, t->lazy);
    apply(t->r, t->lazy);
    t->lazy = 0;
}

void pull(Node *t) {
    if (!t) return;
    t->sz = 1 + getsz(t->l) + getsz(t->r);
    t->sum = t->val + getsum(t->l) + getsum(t->r);
    if (t->l) t->l->p = t;
    if (t->r) t->r->p = t;
}

Node* new_node(int id, ll val, unsigned pri) {
    Node *t = (Node*)malloc(sizeof(Node));
    t->l = t->r = t->p = NULL;
    t->pri = pri;
    t->sz = 1;
    t->val = t->sum = val;
    t->lazy = 0;
    t->id = id;
    return t;
}

Node* merge(Node *a, Node *b) {
    if (!a) { if (b) b->p = NULL; return b; }
    if (!b) { if (a) a->p = NULL; return a; }
    if (a->pri > b->pri) {
        push(a);
        a->r = merge(a->r, b);
        if (a->r) a->r->p = a;
        pull(a);
        a->p = NULL;
        return a;
    } else {
        push(b);
        b->l = merge(a, b->l);
        if (b->l) b->l->p = b;
        pull(b);
        b->p = NULL;
        return b;
    }
}

void split(Node *t, int k, Node **a, Node **b) {
    // first k nodes -> a
    if (!t) {
        *a = *b = NULL;
        return;
    }
    push(t);
    if (getsz(t->l) >= k) {
        split(t->l, k, a, &t->l);
        if (t->l) t->l->p = t;
        pull(t);
        *b = t;
        t->p = NULL;
    } else {
        split(t->r, k - getsz(t->l) - 1, &t->r, b);
        if (t->r) t->r->p = t;
        pull(t);
        *a = t;
        t->p = NULL;
    }
}

int rank_of(Node *x) {
    int res = getsz(x->l) + 1;
    while (x->p) {
        if (x == x->p->r) res += getsz(x->p->l) + 1;
        x = x->p;
    }
    return res;
}

