using int64 = long long;

struct Fenwick {
    int n;
    vector<int64> bit;
    Fenwick(int n_) : n(n_), bit(n_ + 2, 0) {}
    void add(int idx, int64 delta) {
        idx++;
        while (idx <= n + 1) {
            bit[idx] += delta;
            idx += idx & -idx;
        }
    }
    int64 sum(int idx) {
        idx++;
        int64 res = 0;
        while (idx > 0) {
            res += bit[idx];
            idx -= idx & -idx;
        }
        return res;
    }
    int64 range_sum(int l, int r) {
        if (l > r) return 0;
        return sum(r) - sum(l - 1);
    }
};

