#include <bits/stdc++.h>
using namespace std;

using ll = long long;

/*
We need to support on a rooted tree:
1 v x : add x to all nodes in subtree(v)
2 v   : output sum of salaries in subtree(v)
3 p x : add a new node as a child of p with initial salary x

N,Q up to large, so we need dynamic subtree operations.

Key offline idea:
- Read all queries first.
- Build the final tree after all type-3 additions.
- Do one DFS on the final tree to assign Euler tour [tin, tout].
  Then every subtree is a contiguous segment.
- Process queries in original order.

For a node added later, it already has a final Euler position. Before its creation time,
it must not affect sums. We handle this by:
- Initially place salaries of initial N nodes into a Fenwick tree over Euler order.
- When a new node is created, point-add its initial salary at tin[new].
- Range add on subtree(v): add x over [tin[v], tout[v]].
  This naturally affects future descendants too, including nodes not yet created in time.
  But that would be wrong if they receive raises before being hired.
So we need a better decomposition.

Observation:
Salary of a node at time t =
  initial salary at creation + sum of subtree-adds applied to its ancestors/subtree after its creation.

Equivalent handling:
For type-1 on subtree(v), every currently existing node in subtree(v) gains x.
If we offline on final Euler, we'd need to add x only to nodes already created.

We can solve subtree add / subtree sum with node activation times using a segment tree over Euler:
Each node stores:
- cnt: number of active(existing) nodes in segment
- sum_base: sum of current salaries of active nodes
Lazy add applies only to active nodes: sum_base += lazy * cnt

Activation of a new node:
- set cnt=1, sum_base=initial salary
Since previous lazy updates should NOT affect it, this is correct.

Thus:
- Build final tree, Euler.
- Segment tree initially activates only initial nodes with their salaries.
- Type1: range add on subtree(v)
- Type2: range sum on subtree(v)
- Type3: activate the new node at its tin with salary x

All operations O(log M), M = N + number of type3.
*/

struct Query {
    int type;
    int v;
    ll x;
};

struct SegTree {
    struct Node {
        ll sum = 0;   // sum of salaries of active nodes
        ll lazy = 0;  // pending add for active nodes
        int cnt = 0;  // number of active nodes in segment
    };

    int n;
    vector<Node> st;

    SegTree(int n = 0) { init(n); }

    void init(int n_) {
        n = n_;
        st.assign(4 * n, {});
    }

    void pull(int p) {
        st[p].sum = st[p << 1].sum + st[p << 1 | 1].sum;
        st[p].cnt = st[p << 1].cnt + st[p << 1 | 1].cnt;
    }

    void apply(int p, ll val) {
        st[p].sum += val * st[p].cnt;
        st[p].lazy += val;
    }

    void push(int p) {
        if (st[p].lazy != 0) {
            apply(p << 1, st[p].lazy);
            apply(p << 1 | 1, st[p].lazy);
            st[p].lazy = 0;
        }
    }

    void activate(int p, int l, int r, int idx, ll salary) {
        if (l == r) {
            st[p].cnt = 1;
            st[p].sum = salary;
            st[p].lazy = 0;
            return;
        }
        push(p);
        int m = (l + r) >> 1;
        if (idx <= m) activate(p << 1, l, m, idx, salary);
        else activate(p << 1 | 1, m + 1, r, idx, salary);
        pull(p);
    }

    void activate(int idx, ll salary) {
        activate(1, 0, n - 1, idx, salary);
    }

    void range_add(int p, int l, int r, int ql, int qr, ll val) {
        if (qr < l || r < ql) return;
        if (ql <= l && r <= qr) {
            apply(p, val);
            return;
        }
        push(p);
        int m = (l + r) >> 1;
        range_add(p << 1, l, m, ql, qr, val);
        range_add(p << 1 | 1, m + 1, r, ql, qr, val);
        pull(p);
    }

    void range_add(int l, int r, ll val) {
        if (l > r) return;
        range_add(1, 0, n - 1, l, r, val);
    }

    ll range_sum(int p, int l, int r, int ql, int qr) {
        if (qr < l || r < ql) return 0;
        if (ql <= l && r <= qr) return st[p].sum;
        push(p);
        int m = (l + r) >> 1;
        return range_sum(p << 1, l, m, ql, qr) +
               range_sum(p << 1 | 1, m + 1, r, ql, qr);
    }

    ll range_sum(int l, int r) {
        if (l > r) return 0;
        return range_sum(1, 0, n - 1, l, r);
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, Q;
    cin >> N >> Q;

    vector<ll> init_salary;
    init_salary.reserve(N + Q);

    vector<vector<int>> children(N + Q + 5);

    for (int i = 0; i < N; ++i) {
        int p;
        ll a;
        cin >> p >> a;
        init_salary.push_back(a);
        if (p != -1) children[p].push_back(i);
