            cin >> v >> x;
            queries.push_back({1, v, x});
        } else if (t == 2) {
            int v;
            cin >> v;
            queries.push_back({2, v, 0});
        } else {
            int p;
            ll x;
            cin >> p >> x;
            queries.push_back({3, p, x});
            init_salary.push_back(x);
            children[p].push_back(cur_nodes);
            cur_nodes++;
        }
    }

    int M = cur_nodes;

    vector<int> tin(M), tout(M);
    int timer = 0;
    vector<int> st_node, st_it;
    st_node.reserve(M);
    st_it.reserve(M);

    st_node.push_back(0);
    st_it.push_back(0);
