            tout[v] = timer - 1;
            st_node.pop_back();
            st_it.pop_back();
        }
    }

    SegTree seg(M);

    for (int i = 0; i < N; ++i) {
        seg.activate(tin[i], init_salary[i]);
    }

    int next_id = N;
    for (auto &q : queries) {
        if (q.type == 1) {
            int v = q.v;
            seg.range_add(tin[v], tout[v], q.x);
        } else if (q.type == 2) {
            int v = q.v;
            cout << seg.range_sum(tin[v], tout[v]) << '\n';
        } else {
            seg.activate(tin[next_id], init_salary[next_id]);
            next_id++;
        }
    }

    return 0;
}

