    }

    static void dfs(int u) {
        in[u] = timer++;
        for (int v : children[u]) {
            dfs(v);
        }
        out[u] = timer - 1;
    }

    static void add(int idx, long val) {
        idx++;
        while (idx < bit.length) {
            bit[idx] += val;
            idx += idx & -idx;
        }
    }

    static long prefixSum(int idx) {
        idx++;
        long res = 0;
        while (idx > 0) {
            res += bit[idx];
            idx -= idx & -idx;
        }
        return res;
    }

    static void rangeAdd(int l, int r, long val) {
        add(l, val);
        add(r + 1, -val);
    }

    static long rangeSum(int l, int r) {
        return prefixSum(r) - prefixSum(l - 1);
    }
}

