public class Main {
    // -------- Fast Scanner --------
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    // -------- Fenwick Tree --------
    static class Fenwick {
        long[] bit;
        int n;

        Fenwick(int n) {
            this.n = n;
            bit = new long[n + 2];
        }

        void add(int idx, long val) {
            for (int i = idx; i <= n; i += i & -i) bit[i] += val;
        }

        long sum(int idx) {
            long res = 0;
            for (int i = idx; i > 0; i -= i & -i) res += bit[i];
            return res;
        }

        long rangeSum(int l, int r) {
            if (l > r) return 0;
            return sum(r) - sum(l - 1);
        }
    }

    // Range add / range sum using two Fenwicks
    static class RangeFenwick {
        Fenwick b1, b2;
        int n;

        RangeFenwick(int n) {
            this.n = n;
            b1 = new Fenwick(n);
            b2 = new Fenwick(n);
        }

        void internalAdd(Fenwick b, int idx, long val) {
            if (idx <= 0) return;
            b.add(idx, val);
        }

        void rangeAdd(int l, int r, long val) {
            if (l > r) return;
            internalAdd(b1, l, val);
            internalAdd(b1, r + 1, -val);
            internalAdd(b2, l, val * (l - 1));
            internalAdd(b2, r + 1, -val * r);
        }

        long prefixSum(int x) {
            return b1.sum(x) * x - b2.sum(x);
        }

        long rangeSum(int l, int r) {
            if (l > r) return 0;
            return prefixSum(r) - prefixSum(l - 1);
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int N = fs.nextInt();
        int Q = fs.nextInt();

        int maxNodes = N + Q + 5;

        int[] parent = new int[maxNodes];
        long[] salary = new long[maxNodes];

        @SuppressWarnings("unchecked")
        ArrayList<Integer>[] children = new ArrayList[maxNodes];
        for (int i = 0; i < maxNodes; i++) children[i] = new ArrayList<>();

        for (int i = 0; i < N; i++) {
            parent[i] = fs.nextInt();
            salary[i] = fs.nextLong();
            if (parent[i] >= 0) children[parent[i]].add(i);
        }

        int[] type = new int[Q];
        int[] qv = new int[Q];
        long[] qx = new long[Q];

        int curNodes = N;
        for (int i = 0; i < Q; i++) {
            type[i] = fs.nextInt();
            if (type[i] == 1) {
                qv[i] = fs.nextInt();
                qx[i] = fs.nextLong();
            } else if (type[i] == 2) {
                qv[i] = fs.nextInt();
            } else {
                int p = fs.nextInt();
                long x = fs.nextLong();
                qv[i] = p;
                qx[i] = x;

                parent[curNodes] = p;
                salary[curNodes] = x;
                children[p].add(curNodes);
                curNodes++;
            }
        }

        int totalNodes = curNodes;

        // DFS order where each subtree is contiguous even with future insertions
        int[] tin = new int[totalNodes];
        int[] tout = new int[totalNodes];
        int timer = 0;

        int[] stack = new int[totalNodes];
        int[] it = new int[totalNodes];
        int sp = 0;
        stack[sp++] = 0;

        while (sp > 0) {
            int v = stack[sp - 1];
            if (it[v] == 0) {
                tin[v] = ++timer;
            }
            if (it[v] < children[v].size()) {
                int to = children[v].get(it[v]++);
                stack[sp++] = to;
            } else {
                tout[v] = timer;
                sp--;
            }
        }

        RangeFenwick bit = new RangeFenwick(totalNodes + 2);

        for (int v = 0; v < totalNodes; v++) {
            bit.rangeAdd(tin[v], tin[v], salary[v]);
        }

        StringBuilder out = new StringBuilder();
        int nextNewNode = N;

        for (int i = 0; i < Q; i++) {
            if (type[i] == 1) {
                int v = qv[i];
                long x = qx[i];
                bit.rangeAdd(tin[v], tout[v], x);
            } else if (type[i] == 2) {
                int v = qv[i];
                long ans = bit.rangeSum(tin[v], tout[v]);
                out.append(ans).append('\n');
            } else {
                int v = nextNewNode++;
                // salary already initialized, but node becomes active now
                bit.rangeAdd(tin[v], tin[v], salary[v]);
            }
        }

        System.out.print(out.toString());
    }
}
